/** Matches JS or Python dependency manifests. */
const MANIFEST = /(^|\/)(package\.json|requirements[^/]*\.txt|pyproject\.toml|Pipfile)$/;
const anyDep = (label: string, re: RegExp, optional = false) => has(label, MANIFEST, re, { optional });
const CODE = /\.(py|ipynb|m?[jt]sx?)$/;
const ANTHROPIC = 'https://docs.anthropic.com/en/docs';

